        R[2] = newPos;
        R[7] = 0;
      } catch (e) {
        R[2] = -errno(e);
        R[7] = 1;
      }
      return;
    }
    case 60: { // exit
      process.stderr.write(`\n[vm] exit(${a0})\n`);
      process.exit(a0 | 0);
      return;
    }
    case 74: { // fsync
      const fd = a0;
      const hfd = hostFd(fd);
