    case 201: { // time
      const t = Math.floor(Date.now() / 1000);
      if (a0 !== 0) writeI32(a0, t);
      R[2] = t;
      R[7] = 0;
      return;
    }
    case 78: { // gettimeofday - sometimes used directly
      const t = Date.now();
      const sec = Math.floor(t / 1000);
      const usec = (t % 1000) * 1000;
