function errno(e) {
  if (e && e.code) {
    const map = { ENOENT: 2, EACCES: 13, EEXIST: 17, ENOTDIR: 20, EISDIR: 21, EBADF: 9, EINVAL: 22, ENOSPC: 28 };
    return map[e.code] || 5;
  }
  return 5;
}

const fdPos = new Map();

// Override read to use tracked positions
function doRead(fd, bufAddr, count) {
  const hfd = hostFd(fd);
  if (hfd === undefined) return -9;
  try {
    const data = Buffer.alloc(count);
    const pos = fdPos.has(hfd) ? fdPos.get(hfd) : null;
    const n = fs.readSync(hfd, data, 0, count, pos);
    for (let i = 0; i < n; i++) writeU8(bufAddr + i, data[i]);
    if (pos !== null) fdPos.set(hfd, pos + n);
    return n;
  } catch (e) {
    return -errno(e);
  }
