        case 0x04: { // sllv
          const s = R[rs] & 0x1f;
          setR(rd, R[rt] << s);
          break;
        }
        case 0x06: { // srlv
          const s = R[rs] & 0x1f;
          setR(rd, R[rt] >>> s);
          break;
        }
        case 0x07: { // srav
          const s = R[rs] & 0x1f;
          setR(rd, R[rt] >> s);
          break;
        }
        case 0x08: { // jr
          branchTarget = R[rs] >>> 0;
          branchDelay = true;
          break;
        }
        case 0x09: { // jalr
          setR(rd ? rd : 31, pc + 8);
          branchTarget = R[rs] >>> 0;
          branchDelay = true;
          break;
