        case 0x10: { // mfhi
          setR(rd, HI[0]);
          break;
        }
        case 0x11: { // mthi
          HI[0] = R[rs];
          break;
        }
        case 0x12: { // mflo
          setR(rd, LO[0]);
          break;
        }
        case 0x13: { // mtlo
          LO[0] = R[rs];
          break;
        }
        case 0x18: { // mult
          const a = R[rs], b = R[rt];
          const r = Math.imul(a, b);
          LO[0] = r | 0;
          HI[0] = (Math.imul(a, b) - (r | 0)); // not correct for 64-bit
          // Use BigInt for correct 64-bit
          const big = BigInt(a) * BigInt(b);
          LO[0] = Number(big & 0xffffffffn) | 0;
          HI[0] = Number((big >> 32n) & 0xffffffffn) | 0;
          break;
        }
        case 0x19: { // multu
          const a = R[rs] >>> 0, b = R[rt] >>> 0;
          const big = BigInt(a) * BigInt(b);
          LO[0] = Number(big & 0xffffffffn) | 0;
          HI[0] = Number((big >> 32n) & 0xffffffffn) | 0;
          break;
        }
        case 0x1a: { // div
          const a = R[rs], b = R[rt];
          if (b !== 0) {
            // MIPS division truncates toward zero
            LO[0] = Math.trunc(a / b) | 0;
            HI[0] = (a - Math.trunc(a / b) * b) | 0;
          } else { LO[0] = 0; HI[0] = 0; }
          break;
