        case 0x1b: { // divu
          const a = R[rs] >>> 0, b = R[rt] >>> 0;
          if (b !== 0) { LO[0] = (a / b) | 0; HI[0] = (a % b) | 0; } else { LO[0] = 0; HI[0] = 0; }
          break;
        }
        case 0x20: setR(rd, R[rs] + R[rt]); break; // add
